 * <br><code>[0]</code> is the name of the resource;
 * <br><code>[1]</code> onwards are the captured subpatterns.
 */
PE.isResourceNamePresentExp = function (sResourcePattern) {
    var aMatch = null;
    for (var n = 0; n < PE_numberOfResources; n++) {
        var sResourceName = PE.resource[n].Name;

        aMatch = sResourceName.match(sResourcePattern);
        if (aMatch) {
            aMatch[-1] = n;
            aMatch[0] = sResourceName;
            break;
        }
    }

    return aMatch;
}

