    //

    function findNetCoreConfigOffset() {
        var rdataSection = PE.section[".rdata"];

        if (rdataSection) {
            // Before .NET 10 (.NET Core Runtime)
            var versionMarkerOffset = PE.findString(rdataSection.FileOffset, rdataSection.FileSize, ".NETCoreApp,Version=v");

            if (versionMarkerOffset !== -1) {
                return versionMarkerOffset;
            } else if (rdataSection.Number === 1) {
                return PE.findSignature(rdataSection.FileOffset, rdataSection.FileSize, "00 00 00 %% %% 2E %% %% %% %%") + 3; // \0 \0 \0 N1 N2 . N3 -> "\0\0\010.0.8" / "\0\0\010.0.10"
            }
        }
    }

    function findNetFrameworkConfigOffset() {
        return PE.findString(PE.section[0].FileOffset, PE.getSize() - PE.getOverlaySize(), ".NETFramework,Version=v");
    }

    function getNetConfigStringByOffset(configOffset) {
        var result = PE.getString(configOffset);

        if (result.indexOf("=") !== -1) {
            result = result.split("=")[1];
            if (result && result[0] !== 'v' && result.length > 7)
                result = String();

            result = result.substr(1);
        } else if (!/^\d{2}(\.\d+)+$/.test(result)) {
            result = String();
        }

