includeScript("Borland");

function getVersion() {
    if (PE.isNet()) {
        sOptions = ".NET";

        if (PE.isNetObjectPresent("Borland.Vcl.Types")) {
            sVersion = "8";
        } else if (PE.isNetObjectPresent("Borland.Eco.Interfaces")) {
            sVersion = "8 Eco WinForm";
        } else if (PE.isNetObjectPresent("Borland.Delphi.System") &&
            PE.isNetObjectPresent("WinForm")) {
            sVersion = "8 WinForm";
        } else if (PE.isNetObjectPresent("Borland.Delphi.Units")) {
            sVersion = "2005";
        } else if (PE.isNetObjectPresent("Borland.Studio.Delphi")) {
            sName = "Embarcadero Delphi";
            sVersion = "XE*";
        } else {
            return false;
        }

        return true;
    }

    var nSectionOffset = PE.section[0].FileOffset,
        nSectionSize = PE.section[0].FileSize,
        nOffset = nSectionOffset,
        nSize = nSectionSize,
        nOffset2,
        nAddress,
        nLng,
        nLng1,
        bNewVersion = false;

    var nAddressSize = PE.is64() ? 8 : 4;

    while (nSize > 0) {
        nOffset = PE.findSignature(nOffset, nSize, "0708'TControl'");

        if (nOffset == -1) {
            break;
        }

        nAddress = PE.readDword(nOffset + 10);
        nOffset2 = PE.VAToOffset(nAddress);

        if (nOffset2 != -1) {
            if (nOffset2 >= nSectionOffset && (nOffset2 < nSectionOffset + nSectionSize)) {
                nLng = PE.readDword(nOffset2 - 10 * nAddressSize);
                nLng1 = PE.readDword(nOffset2 - 10 * nAddressSize - 11 * nAddressSize);

                switch (nLng) {
                    case 0:
                        if (nLng1 == 0x746E4907) {
                            sVersion = "3";
                        } else if (nLng1 == 0x4F540774) {
                            sVersion = "2";
                        }

                        break;
                    case 0x0B4: sVersion = "C++ Builder"; break;
                    case 0x114: sVersion = "4"; break;
                    case 0x120: sVersion = "5"; break;
                    case 0x128: sVersion = "6 CLX"; break;
                    case 0x12C: sVersion = "7 CLX"; break;
                    case 0x138: sVersion = "Kylix"; break;
                    case 0x15C:
                    case 0x160: sVersion = (nLng1 == 0x40100000 || nLng1 == 0x100000) ? "7" : "6"; break;
                    case 0x164: sVersion = "2005"; break;
                    case 0x190: sVersion = "2006"; break;

                    default:
                        nLng = PE.readDword(nOffset2 - 13 * nAddressSize);

                        if (nLng == 0x1A4) {
                            sName = "Embarcadero Delphi";
                            sVersion = "2009";
                        } else if (nLng == 0x1AC) {
                            var packageInfoResource = PE.resource["PACKAGEINFO"];

                            if (packageInfoResource) {

                                nOffset = packageInfoResource.Offset;
                                nSize = packageInfoResource.Size;

                                if (PE.isSignaturePresent(nOffset, nSize, "'ExcUtils'")) {
                                    sName = "Embarcadero Delphi";
                                    sVersion = "XE";
                                } else if (PE.isSignaturePresent(nOffset, nSize, "'StrUtils'")) {
                                    sName = "Embarcadero Delphi";
                                    sVersion = "2010";
                                } else {
                                    sName = "Embarcadero Delphi";
                                    sVersion = "2010 or XE";
                                }
                            }
                        } else if (nLng == 0x1B4) {
                            // 32
                            sName = "Embarcadero Delphi";
                            sVersion = "XE2-XE4";
                        } else if (nLng == 0x2F0 || nLng == 0x2F8) {
                            // 64
                            sName = "Embarcadero Delphi";
                            sVersion = "XE2";
                        } else if (nLng == 0x1BC) {
                            // 32
                            sName = "Embarcadero Delphi";
                            sVersion = "XE5-XE6";
                            bNewVersion = true;
                        } else {
                            if (nAddressSize == 8) {
                                nLng = PE.readDword(nOffset2 - 16 * nAddressSize);
                                if (nLng == 0x2F8) {
                                    // 64
                                    sName = "Embarcadero Delphi";
                                    sVersion = "XE3-XE4";
                                } else if (nLng == 0x308) {
                                    // 64
                                    sName = "Embarcadero Delphi";
                                    sVersion = "XE5-XE6";
                                    bNewVersion = true;
                                }
                            }
                        }
                }

                if (sVersion && !bNewVersion) {
                    return true;
                }
            }
        }

        nOffset++;
        nSize = nSectionSize - (nOffset - nSectionOffset);
    }

    if (PE.resource["PACKAGEINFO"]) {
        nOffset = PE.resource["PACKAGEINFO"].Offset;
        nSize = PE.resource["PACKAGEINFO"].Size;

        if (PE.isSignaturePresent(nOffset, nSize, "'System.SysUtils'")) {
            sName = "Embarcadero Delphi";
            sVersion = "XE2-XE6";
