        } else if (PE.isSignaturePresent(nOffset, nSize, "'ExcUtils'")) {
            sName = "Embarcadero Delphi";
            sVersion = "XE";
        } else if (PE.isSignaturePresent(nOffset, nSize, "'StrUtils'")) {
            sName = "Embarcadero Delphi";
