            else if (PE.compareEP("48 83 EC .. 48 8D 0D .. .. .. .. FF 15 .. .. .. .. 83 F8 00 74 .. 48 83 C4 58 48 89 25 .. .. .. .. E9 .. .. .. .. 48 31 C9") ||
