            /*
            - Dragon Quest XI
            - Resident Evil 4
            - South Park
            - Tekken 7
            - Trials of Mana
            - Total War: Warhammer 2
            */
            else if (isSectionsLikeDenuvo && imageSearchSize > 0 && PE.isSignaturePresent(firstSectionOffset, imageSearchSize, "64 65 6E 75 76 6F 5F 61 74 64 00 00 00 00 00 00")) {
                bDetected = true;
