            // Check if steam_api64.dll present
            if (isSectionsLikeDenuvo && PE.isLibraryPresent("steam_api64.dll")) {
                sOptions = "Steam";
                bDetected = true;
            }

            // Check if eossdk-win32-shipping.dll present
            if (isSectionsLikeDenuvo && PE.isLibraryPresent("eossdk-win64-shipping.dll")) {
                sOptions = "Epic Games";
                bDetected = true;
            }

            // Check if denuvo64.dll present
            if (isSectionsLikeDenuvo && PE.isLibraryPresent("denuvo64.dll")) {
                sOptions = "x64";
                bDetected = true;
            }

        } else {
            // Pro Evolution Soccer 2017, Champions of Anteria
            if (PE.compareEP("55 89 E5 8D ?? ?? ?? ?? ?? ?? E8 ?? ?? ?? ?? E8 ?? ?? ?? ?? E8 ?? ?? ?? ?? E8 ?? ?? ?? ??")) {
                sVersion = "1.0";
